/*
 * One-time golden-vector extractor (plan prompt W0.4, ADR-0009).
 *
 * Emits golden_vectors/wm_select.json content on stdout, generated by
 * the wack_a_mole static-inline spray core itself — the vectors are
 * EXTRACTED from the source implementation (wam_theta / wam_spray_key /
 * wam_spray_next / wam_lookup_path), never hand-derived. The canonical
 * profile b = [127,400,200,173,124] over m=1024 is the one wack_a_mole
 * tests/test_spray.c uses for its distribution and discrepancy legs.
 *
 * Not part of the sdf build. Regenerate only when the source repo
 * baseline changes (import map §6.1):
 *
 *   cc -O2 -o /tmp/gen_goldens tools/gen_goldens.c \
 *      -I/home/aimlrn/fw_projects/wack_a_mole/include
 *   /tmp/gen_goldens > golden_vectors/wm_select.json
 */

#include "wam/profile.h"
#include "wam/spray.h"

#include <stdio.h>
#include <string.h>

/* The test_spray.c canonical profile: n=5, m=1024. */
#define N 5u
static const uint32_t B[N] = {127, 400, 200, 173, 124};

/* Construct a wam_profile_t without linking profile.c: b copied, c as
 * prefix sums, lut NULL. wam_lookup_path's c[] walk is the exact
 * semantics the sdf CDF construction implements, so sequences produced
 * here must match wm_select unit-for-unit. */
static void mk_profile(wam_profile_t *p, uint32_t *bbuf, uint32_t *cbuf) {
    memset(p, 0, sizeof(*p));
    p->m = 1024;
    p->ell = 10;
    p->n = N;
    p->b = bbuf;
    p->c = cbuf;
    memcpy(bbuf, B, sizeof(B));
    uint32_t acc = 0;
    for (uint8_t i = 0; i < N; i++) {
        acc += B[i];
        cbuf[i] = acc;
    }
    p->lut = NULL;
}

/* Construct spray state without linking spray.c: fields per
 * wam_spray_init's documented postconditions (sa masked, sb forced
 * odd — the callers' values already satisfy both). */
static void mk_spray(wam_spray_t *s, uint32_t j, uint8_t method) {
    memset(s, 0, sizeof(*s));
    s->m = 1024;
    s->ell = 10;
    s->j = j;
    s->sa = 333;
    s->sb = 735;
    s->method = method;
}

static void emit_picks(const char *key, const char *requires, uint32_t from,
                       uint32_t count, uint8_t method, const wam_profile_t *p,
                       int comma) {
    wam_spray_t s;
    mk_spray(&s, from, method);
    printf("  \"%s\": {", key);
    if (requires != NULL)
        printf("\"requires\": \"%s\", ", requires);
    printf("\"from\": %u, \"count\": %u, \"paths\": [", from, count);
    for (uint32_t i = 0; i < count; i++)
        printf("%s%u", i ? ", " : "", wam_spray_next(&s, p));
    printf("]}%s\n", comma ? "," : "");
}

static void emit_window(uint32_t from, uint32_t len, uint8_t method,
                        const wam_profile_t *p, int comma) {
    uint32_t counts[N] = {0};
    wam_spray_t s;
    mk_spray(&s, from, method);
    for (uint32_t i = 0; i < len; i++)
        counts[wam_spray_next(&s, p)]++;
    printf("    {\"from\": %u, \"len\": %u, \"counts\": [%u, %u, %u, %u, %u]}%s\n",
           from, len, counts[0], counts[1], counts[2], counts[3], counts[4],
           comma ? "," : "");
}

int main(void) {
    wam_profile_t p;
    uint32_t bbuf[N], cbuf[N];
    mk_profile(&p, bbuf, cbuf);

    printf("{\n");
    printf("  \"comment\": \"%s\",\n",
           "Golden vectors pinning the sdf WM dispatch to the wack_a_mole "
           "spray core.");
    printf("  \"extraction\": \"%s\",\n",
           "tools/gen_goldens.c runs the wam_theta / wam_spray_key / "
           "wam_spray_next / wam_lookup_path static-inline core at baseline "
           "a0f0422 (ADR-0009: filled from the source, never re-derived); the "
           "profile is the test_spray.c canonical. Validated groups against "
           "the v1 ABI: theta_ell10, plain_sequence, plain_windows. Seed "
           "groups require ADR-0007 methods (W2.1) and count as pending "
           "until then.");
    printf("  \"provenance\": {\"source\": \"wack_a_mole\", \"commit\": \"a0f0422\",\n");
    printf("                 \"profile\": {\"m\": 1024, \"n\": 5,\n");
    printf("                              \"b\": [127, 400, 200, 173, 124]}},\n");

    printf("  \"theta_ell10\": [\n");
    {
        static const uint32_t js[] = {0, 1, 2, 3, 249, 512, 768, 1023};
        for (size_t i = 0; i < sizeof(js) / sizeof(js[0]); i++)
            printf("    [%u, %u]%s\n", js[i], wam_theta(js[i], 10),
                   i + 1 < sizeof(js) / sizeof(js[0]) ? "," : "");
    }
    printf("  ],\n");

    emit_picks("plain_sequence", NULL, 0, 64, WAM_SPRAY_PLAIN, &p, 1);

    printf("  \"plain_windows\": [\n");
    {
        static const uint32_t starts[] = {0, 1, 500, 1023};
        static const uint32_t lens[] = {64, 1000, 1024, 10240};
        for (size_t si = 0; si < sizeof(starts) / sizeof(starts[0]); si++)
            for (size_t li = 0; li < sizeof(lens) / sizeof(lens[0]); li++)
                emit_window(starts[si], lens[li], WAM_SPRAY_PLAIN, &p,
                            !(si == 3 && li == 3));
    }
    printf("  ],\n");

    /* seed groups carry a requires tag: ADR-0007 methods land with W2.1 */
    emit_picks("seed_shuffle1", "wm.method.shuffle1", 0, 64, WAM_SPRAY_SHUFFLE1,
               &p, 1);
    emit_picks("seed_shuffle2", "wm.method.shuffle2", 0, 64, WAM_SPRAY_SHUFFLE2,
               &p, 0);

    printf("}\n");
    return 0;
}

